import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();
  root.userData.handlers = {};

  // ---------- Backdrop ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color('#1a1a22'), color('#121218'), uv().y);
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- Kicker Text ----------
  const kickerItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = kickerItems.find(i => i.role === 'kicker');
  if (kickerItem) {
    const kicker = ctx.fontAtlas.createText(kickerItem.text, {
      fontSize: 9,
      color: '#e8ecf2',
      align: 'center',
    });
    // position kicker 0.3 units above the tile grid (grid half‑height = 0.745)
    kicker.position.set(0, 0.745 + 0.3, 0);
    root.add(kicker);
  }

  // ---------- Tile Grid ----------
  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;
  const cols = 3;
  const rows = 2;
  const totalW = cols * tileW + (cols - 1) * gap; // 3.5
  const totalH = rows * tileH + (rows - 1) * gap; // 1.49
  const startX = -totalW / 2 + tileW / 2;
  const startY = -totalH / 2 + tileH / 2;

  const brandItems = kickerItems.filter(i => i.role === 'brand-mark');
  const timelines = [];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const item = brandItems[idx];
      const tileGroup = new Group();

      // ---- Tile Mesh ----
      const geom = new PlaneGeometry(tileW, tileH);
      const mat = new MeshStandardNodeMaterial();
      mat.metalness = 0.5;
      mat.roughness = 0.55;
      mat.clearcoat = 0.2;
      mat.transparent = true;
      mat.opacity = 0; // start invisible for entrance
      // vertical albedo gradient
      mat.colorNode = mix(color('#1a1a22'), color('#121218'), uv().y);
      // anisotropy
      mat.anisotropy = 0.6;
      mat.anisotropyDirection = ctx.THREE.Vector3(1, 0, 0);
      const mesh = new Mesh(geom, mat);
      tileGroup.add(mesh);

      // ---- Position ----
      const x = startX + c * (tileW + gap);
      const y = startY + (rows - 1 - r) * (tileH + gap);
      tileGroup.position.set(x, y, 0);

      // ---- Brand Text ----
      if (item) {
        const txt = ctx.fontAtlas.createText(item.text, {
          fontSize: 13,
          color: '#e8ecf2',
          align: 'center',
        });
        // set initial opacity 0.78
        txt.traverse(o => {
          if (o.material) {
            o.material.transparent = true;
            o.material.opacity = 0.78;
          }
        });
        txt.position.set(0, 0, 0.001); // slightly above the plane
        tileGroup.add(txt);

        // ---- Hover Handlers ----
        const hoverIn = () => {
          gsap.to(mesh.position, { z: 0.05, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
          gsap.to(txt.material, { opacity: 1.0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        };
        const hoverOut = () => {
          gsap.to(mesh.position, { z: 0, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
          gsap.to(txt.material, { opacity: 0.78, duration: 0.16, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' });
        };
        tileGroup.userData.handlers = {
          pointerover: hoverIn,
          pointerout: hoverOut,
        };
      }

      root.add(tileGroup);

      // ---- Entrance Animation ----
      const tl = gsap.timeline();
      tl.from(mesh.position, {
        y: y + 0.2,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0);
      tl.from(mat, {
        opacity: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      }, 0);
      timelines.push(tl);
    }
  }

  // Stagger the entrance timelines
  timelines.forEach((tl, i) => {
    tl.delay(i * 0.08);
  });

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    root.traverse(o => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (o.material.map) o.material.map.dispose();
        o.material.dispose();
      }
    });
  };

  return root;
}
